INSERT INTO creator_profiles (user_id, handle, display_name, bio, tagline, is_public, is_demo) VALUES ('65c386d3-e375-5e81-8fe8-c07818364b44', 'blue-hour', '블루아워', '가까운 미래의 도시와 사람의 기억을 다루는 가상 창작자입니다. 시네마틱 장면을 출발점으로 이야기를 확장합니다.', '현실과 SF 사이의 한 장면.', true, true) ON CONFLICT DO NOTHING;
