INSERT INTO assets (id, workspace_id, storage_key, mime_type, width, height, source, provenance) VALUES ('e95dae11-d3f2-5462-8d0b-97a4d47abaf8', '3874cfbe-373c-50b7-8415-fbdb0791bf6e', 'showcase/rain-city.png', 'image/png', 1536, 1024, 'demo', '{"generatedWith":"image_gen","fictional":true}') ON CONFLICT DO NOTHING;
INSERT INTO projects (id, workspace_id, title, format, stage) VALUES ('3498573b-7ac0-512f-8d1d-e9d51f8970a4', 'c6e23cda-e53f-5ecf-8ac6-3b910d5ad380', '월광우체국', 'novel', 'review') ON CONFLICT DO NOTHING;
INSERT INTO stories (id, workspace_id, project_id, premise, planned_episodes) VALUES ('bde10797-1511-5f1e-836e-1dec6cede7e8', 'c6e23cda-e53f-5ecf-8ac6-3b910d5ad380', '3498573b-7ac0-512f-8d1d-e9d51f8970a4', '수신인이 잊은 기억을 배달하는 우체국. 마지막 편지에는 배달부 자신의 이름이 적혀 있었다.', 2) ON CONFLICT DO NOTHING;
INSERT INTO episodes (id, workspace_id, story_id, number, title, body, status) VALUES ('8f2230f6-192e-5b86-8883-5313567cb787', 'c6e23cda-e53f-5ecf-8ac6-3b910d5ad380', 'bde10797-1511-5f1e-836e-1dec6cede7e8', 1, '수신인 없는 편지', '우체국의 시계는 달이 뜨면 거꾸로 돌았다. 서린은 아무도 묻지 않는 그 규칙을 지키며 서른 번째 밤의 배달 가방을 열었다. 오늘 들어온 편지는 단 한 통. 봉투에는 주소도 이름도 없었지만, 손바닥에 올리자 오래된 바다 냄새가 났다.

‘잊어버린 곳으로 가면 돼.’ 국장은 늘 그렇게 말했다. 서린은 언덕 끝의 파란 대문을 떠올렸다. 그곳에는 집이 없었다. 재작년 화재 이후로 텅 빈 터만 남아 있었다. 그런데도 편지는 그쪽으로 가라고, 가방 안에서 희미하게 빛났다.

지붕을 건너던 서린은 처음 보는 발자국을 발견했다. 눈도 내리지 않은 기와 위에 하얀 자국이 이어졌다. 파란 대문 앞에서 자국이 끊겼다. 문틈으로 어린 목소리가 들렸다.

‘오늘은 엄마가 기억했나요?’

서린이 봉투를 뒤집었다. 빈 종이라고 생각한 뒷면에 글씨가 떠올랐다. 배달하지 말 것. 보낸 사람의 이름은 분명 서린이었다.', 'ready') ON CONFLICT DO NOTHING;
INSERT INTO episode_revisions (episode_id, workspace_id, story_id, version, body, plot) VALUES ('8f2230f6-192e-5b86-8883-5313567cb787', 'c6e23cda-e53f-5ecf-8ac6-3b910d5ad380', 'bde10797-1511-5f1e-836e-1dec6cede7e8', 1, '우체국의 시계는 달이 뜨면 거꾸로 돌았다. 서린은 아무도 묻지 않는 그 규칙을 지키며 서른 번째 밤의 배달 가방을 열었다. 오늘 들어온 편지는 단 한 통. 봉투에는 주소도 이름도 없었지만, 손바닥에 올리자 오래된 바다 냄새가 났다.

