INSERT INTO membership_plans (code, name, state, monthly_price_krw, yearly_price_krw, proposed_features) VALUES ('creator', 'Creator', 'coming_soon', NULL, NULL, '["Free의 기본 제작 흐름","캐릭터 시트·프롬프트 템플릿 확장","회차별 원고와 복선 관리 중심 구성","이미지·영상 생성 이용량 확장 예정","MCP를 통한 대화형 제작"]') ON CONFLICT DO NOTHING;
INSERT INTO membership_plans (code, name, state, monthly_price_krw, yearly_price_krw, proposed_features) VALUES ('pro', 'Pro', 'coming_soon', NULL, NULL, '["Creator의 제작 구성","장편·다회차 프로젝트를 위한 이용량","캐릭터·스타일 템플릿 활용 확대","이미지·영상 생성 이용량 추가 확대 예정","생성 작업 우선 처리 검토 중"]') ON CONFLICT DO NOTHING;
